import dev.kstool.pack.sdk.PackSdk;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;

/**
 * The artifacts of the postgres example, generated by the Java SDK, are the ones the Go example generates, byte for
 * byte (examples/postgres/golden, written by {@code go test ./examples/postgres/go}). From examples/postgres/java:
 *
 * <pre>
 * javac --release 21 -d out $(find ../../../sdk/java/src/main -name '*.java') Postgres.java PostgresTest.java
 * java -cp out PostgresTest
 * </pre>
 */
public class PostgresTest {
    private static final Path GOLDEN = Path.of("../golden");

    static List<String> tree(Path dir) throws IOException {
        try (Stream<Path> s = Files.walk(dir)) {
            List<String> out = new ArrayList<>(s.filter(Files::isRegularFile).map(p -> dir.relativize(p).toString()).toList());
            out.sort(Comparator.naturalOrder());
            return out;
        }
    }

    public static void main(String[] args) throws IOException {
        Path out = Files.createTempDirectory("postgres");
        PackSdk.generate(out, new Postgres());
        int failed = 0;
        if (!tree(GOLDEN).equals(tree(out))) {
            System.err.println("FAIL: files: golden " + tree(GOLDEN) + ", got " + tree(out));
            failed++;
        }
        for (String rel : tree(GOLDEN)) {
            if (Files.exists(out.resolve(rel)) && !new String(Files.readAllBytes(GOLDEN.resolve(rel))).equals(new String(Files.readAllBytes(out.resolve(rel))))) {
                System.err.println("FAIL: " + rel + " differs from the Go example's");
                failed++;
            }
        }
        if (failed > 0) System.exit(1);
        System.out.println("ok");
    }
}
